import { PERMISSIONS, SYSTEM_ROLE_KEYS, SYSTEM_ROLE_PERMISSIONS } from "./permissions";

/** Markdown permission matrix generated from the code, so the documentation cannot drift (tests/unit/docs.test.ts). */
export function rbacMatrixMarkdown(): string {
  const lines = [
    "<!-- GENERATED by `pnpm docs:generate` from src/authz/permissions.ts. Do not edit by hand. -->",
    "",
    `| Permission | ${SYSTEM_ROLE_KEYS.join(" | ")} |`,
    `|---|${SYSTEM_ROLE_KEYS.map(() => ":-:").join("|")}|`,
  ];
  for (const p of PERMISSIONS) lines.push(`| \`${p}\` | ${SYSTEM_ROLE_KEYS.map((r) => (SYSTEM_ROLE_PERMISSIONS[r].includes(p) ? "✓" : "")).join(" | ")} |`);
  lines.push("", `${PERMISSIONS.length} permissions; \`orgadmin\` holds all of them.`, "");
  return lines.join("\n");
}
